/* Configuration for the vendored libyaml 0.2.5 sources.
 *
 * Upstream generates this file with `configure` or CMake. The WASM build
 * only needs the version macros, so they are written out here.
 */
#ifndef ZAML_LIBYAML_CONFIG_H
#define ZAML_LIBYAML_CONFIG_H

#define YAML_VERSION_MAJOR 0
#define YAML_VERSION_MINOR 2
#define YAML_VERSION_PATCH 5
#define YAML_VERSION_STRING "0.2.5"

#endif /* ZAML_LIBYAML_CONFIG_H */
